#!/usr/bin/env python3
"""Send one command to the STM32 tabletop KeeLoq receiver test harness."""

from __future__ import annotations

import argparse
import os
import termios


SCENARIOS = {
    "stale": (b"r", "measured previously-used original frame"),
    "synthetic-stale": (b"s", "same stale fields generated by the new encoder"),
    "zero-hop": (b"z", "original serial/button with zero hopping field"),
    "plaintext-counter": (b"p", "original serial/button with incrementing plaintext counter"),
    "random-hop": (b"x", "original serial/button with changing pseudorandom hopping field"),
    "different-serial": (b"d", "copier serial/button with zero hopping field"),
}


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("scenario", choices=SCENARIOS)
    parser.add_argument("--port", default="/dev/ttyUSB0")
    args = parser.parse_args()

    command, description = SCENARIOS[args.scenario]
    fd = os.open(args.port, os.O_RDWR | os.O_NOCTTY)
    try:
        settings = termios.tcgetattr(fd)
        settings[0] = 0
        settings[1] = 0
        settings[2] = termios.CS8 | termios.CLOCAL | termios.CREAD
        settings[3] = 0
        settings[4] = termios.B115200
        settings[5] = termios.B115200
        termios.tcsetattr(fd, termios.TCSANOW, settings)
        os.write(fd, command)
        termios.tcdrain(fd)
    finally:
        os.close(fd)
    print(f"sent {args.scenario}: {description}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
